// Formata o payload de alerta do Grafana (unified alerting webhook) em uma
// mensagem de texto simples pro WhatsApp. Ver estrutura do payload em:
// https://grafana.com/docs/grafana/latest/alerting/configure-notifications/manage-contact-points/integrations/webhook-notifier/
// Le direto do node do Webhook porque o node "Configuração" (Set) substitui
// o $json inteiro pelos campos fixos, perdendo o body original.
const body = $('Webhook (Grafana)').first().json.body || {};
const alerts = body.alerts || [];
const status = (body.status || 'unknown').toUpperCase();
const title = body.title || (alerts[0] && alerts[0].labels && alerts[0].labels.alertname) || 'Alerta Grafana';

const lines = [`[${status}] ${title}`, ''];

for (const a of alerts) {
  const name = (a.labels && a.labels.alertname) || 'alerta';
  const summary = (a.annotations && (a.annotations.summary || a.annotations.description)) || '';
  const instance = (a.labels && (a.labels.instance || a.labels.client)) || '';
  lines.push(`- ${name}${instance ? ' (' + instance + ')' : ''}`);
  if (summary) lines.push(`  ${summary}`);
}

const text = lines.join('\n');
const cfg = $('Configuração').first().json;
return [{ json: { text, ...cfg } }];
